    <div className="wallet-filterbar cashout-filter"><div className="wide"><UserPicker users={users} value={users.find((u) => u.email === filters.emailId) ?? null} onChange={(u) => setFilters({ ...filters, emailId: u?.email ?? "" })} loading={loadingUsers} error={usersError} retry={retryUsers}/></div><label>Status<select value={filters.status} onChange={(e) => setFilters({ ...filters, status: e.target.value })}><option value="">All statuses</option><option>PENDING</option><option>SUCCESS</option><option>FAILED</option></select></label><label>Type<select value={filters.type} onChange={(e) => setFilters({ ...filters, type: e.target.value })}><option value="">All types</option><option>UPI</option><option>BANK</option></select></label><label>Transaction ID<input value={filters.transactionId} onChange={(e) => setFilters({ ...filters, transactionId: e.target.value })}/></label><label>Created from<input type="datetime-local" value={filters.createdFrom} onChange={(e) => setFilters({ ...filters, createdFrom: e.target.value })}/></label><label>Created to<input type="datetime-local" value={filters.createdTo} onChange={(e) => setFilters({ ...filters, createdTo: e.target.value })}/></label><button className="wallet-primary" onClick={apply}>Apply filters</button><button className="wallet-secondary" onClick={() => { const empty = { emailId: "", status: "", type: "", transactionId: "", createdFrom: "", createdTo: "" }; setFilters(empty); setApplied(empty); data.setPageNumber(0); }}>Reset</button></div>
    {data.error ? <Retry error={data.error} retry={() => void data.load()}/> : data.busy && !data.page ? <Loading/> : <><TableWrap><table><thead><tr><th>ID / user</th><th>Coins</th><th>Amount</th><th>Type</th><th>Details</th><th>Status</th><th>Transaction</th><th>Remarks</th><th>Created</th><th>Updated</th><th>Actions</th></tr></thead><tbody>{data.page?.content.map((c) => <tr key={c.id}><td>#{c.id}<small>{c.userEmail} · {c.userId}</small></td><td>{number(c.amountCoins)} MP</td><td>{cash(c.amountRupees)}</td><td><Badge value={c.type}/></td><td>{maskDetails(c.details)}</td><td><Badge value={c.status}/></td><td>{c.transactionId || "—"}</td><td>{c.remarks || "—"}</td><td>{date(c.createdAt)}</td><td>{date(c.updatedAt)}</td><td><button className="wallet-row-button" onClick={() => setDetail(c)}>Details</button><button className="wallet-row-button" onClick={() => setEditing(c)}>Update status</button></td></tr>)}{!data.page?.content.length && <EmptyRow columns={11} text="No cashout requests match these filters."/>}</tbody></table></TableWrap><Pager page={data.page} setPage={data.setPageNumber} setSize={data.setSize}/></>}
    {detail && <Drawer title={`Cashout #${detail.id}`} close={() => setDetail(null)}><Info items={[["User ID", detail.userId], ["User Email", detail.userEmail], ["Amount", `${number(detail.amountCoins)} MP Coins`], ["Amount rupees", cash(detail.amountRupees)], ["Type", detail.type], ["Payment details", maskDetails(detail.details)], ["Status", detail.status], ["Transaction ID", detail.transactionId], ["Remarks", detail.remarks], ["Created", date(detail.createdAt)], ["Updated", date(detail.updatedAt)]]}/><p className="wallet-note">Payment details are masked when they resemble an email, UPI address, or account number.</p></Drawer>}
