  async function status(p: Package) { if (!window.confirm(`Set package “${p.name}” (#${p.id}) ${p.active ? "inactive" : "active"}? Inactive packages may no longer be available for new purchases.`)) return; try { await api<Package>(`${BASE}/packages/${p.id}/status`, { method: "PATCH", body: JSON.stringify({ active: !p.active }) }); onSuccess(`Package ${p.name} ${p.active ? "deactivated" : "activated"}.`); await load(); } catch (e) { onError(messageOf(e)); } }
